import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useIntl } from 'react-intl';

import { BasicContainer } from 'components';

import { formatScopedGeoTitle } from '../../utils/formatScopedGeoTitle';
import { ContributionSection } from './components/ContributionSection';
import { DeepDiveSection } from './components/DeepDiveSection';
import { OvertimeSection } from './components/OvertimeSection';
import { getPerformanceAndBreakdownContextKey } from './config/performanceAndBreakdownDeepDive';
import {
  PERFORMANCE_AND_BREAKDOWN_GLOBAL_TITLE_I18N_ID,
  PERFORMANCE_AND_BREAKDOWN_SCOPED_TITLE_I18N_ID,
} from './constants';
import {
  usePerformanceAndBreakdownFilters,
  usePerformanceAndBreakdownLocalFilters,
} from './hooks';
import { StyledSectionsStack } from './PerformanceAndBreakdown.styles';
import type {
  PerformanceAndBreakdownInnovationStageFilter,
  PerformanceAndBreakdownWaterfallContextKey,
} from './types';
import { getPerformanceAndBreakdownTitleScope } from './utils/getPerformanceAndBreakdownTitleScope';

interface PerformanceAndBreakdownProps {
  dataTestId?: string;
}

export const PerformanceAndBreakdown: React.FC<
  PerformanceAndBreakdownProps
> = ({ dataTestId }) => {
  const { formatMessage } = useIntl();
  usePerformanceAndBreakdownLocalFilters();
  const { applied, isGlobalZone, dataFilters, kpi } =
    usePerformanceAndBreakdownFilters();

  const contextKey = useMemo(
    (): PerformanceAndBreakdownWaterfallContextKey =>
      getPerformanceAndBreakdownContextKey(applied, isGlobalZone),
    [applied, isGlobalZone],
  );

  const sectionTitle = useMemo(
    () =>
      formatScopedGeoTitle(formatMessage, {
        applied,
        dataFilters,
        globalTitleId: PERFORMANCE_AND_BREAKDOWN_GLOBAL_TITLE_I18N_ID,
        scopedTitleId: PERFORMANCE_AND_BREAKDOWN_SCOPED_TITLE_I18N_ID,
        resolveScope: getPerformanceAndBreakdownTitleScope,
      }),
    [applied, dataFilters, formatMessage],
  );

  const [innovationStageFilter, setInnovationStageFilter] =
    useState<PerformanceAndBreakdownInnovationStageFilter | null>(null);
  const [contributionChartResetKey, setContributionChartResetKey] = useState(0);

  useEffect(() => {
    setInnovationStageFilter(null);
    setContributionChartResetKey((key) => key + 1);
  }, [applied]);

  const handleInnovationStageSelect = useCallback(
    (filter: PerformanceAndBreakdownInnovationStageFilter | null) => {
      setInnovationStageFilter(filter);
    },
    [],
  );

  const handleClearInnovationStage = useCallback(() => {
    setInnovationStageFilter(null);
    setContributionChartResetKey((key) => key + 1);
  }, []);

  return (
    <BasicContainer
      dataTestId={dataTestId}
      fullWidth
      header={{ title: sectionTitle, titleSize: 'H3' }}
      layout={{ background: '#fafafa', border: 'gray', bodyPadding: false }}
    >
      <StyledSectionsStack>
        <OvertimeSection
          kpi={kpi}
          dataTestId={
            dataTestId ? `${dataTestId}-overtime` : 'innovation-hub-pb-overtime'
          }
        />
        <ContributionSection
          kpi={kpi}
          innovationStageFilter={innovationStageFilter}
          onInnovationStageSelect={handleInnovationStageSelect}
          chartResetKey={contributionChartResetKey}
          dataTestId={
            dataTestId
              ? `${dataTestId}-contribution`
              : 'innovation-hub-pb-contribution'
          }
        />
        <DeepDiveSection
          contextKey={contextKey}
          kpi={kpi}
          innovationStageFilter={innovationStageFilter}
          onClearInnovationStage={handleClearInnovationStage}
          dataTestId={
            dataTestId
              ? `${dataTestId}-deep-dive`
              : 'innovation-hub-pb-deep-dive'
          }
        />
      </StyledSectionsStack>
    </BasicContainer>
  );
};
